def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count cooperation
    opp_coops = 0
    my_coops = 0
    for h in history:
        if h[1] == 'C':
            opp_coops += 1
        if h[0] == 'C':
            my_coops += 1

    opp_d = n - opp_coops
    my_d = n - my_coops
    last_me, last_opp = history[-1]

    # First few rounds: cooperate to establish cooperation
    if n < 4:
        return 'C'

    # Recent window analysis
    w = 6 if n >= 6 else n
    recent = history[-w:]
    rec_opp_c = 0
    rec_opp_d = 0
    for h in recent:
        if h[1] == 'C':
            rec_opp_c += 1
        else:
            rec_opp_d += 1

    # Opponent defection streak (current)
    opp_streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak_d += 1
        else:
            break

    # My defection streak
    my_streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_streak_d += 1
        else:
            break

    # Very cooperative opponent (rarely defects) -> cooperate, probe rarely
    if opp_d <= 1 and n >= 10:
        if n < 92 and n % 31 == 0:
            return 'D'
        return 'C'

    # Highly cooperative opponent
    if opp_coops >= n * 0.85:
        # if they recently defected once, forgive immediately
        if last_opp == 'D':
            if opp_streak_d <= 1:
                return 'C'
            return 'D'
        return 'C'

    # Highly defective opponent -> mostly defect, brief forgiveness attempts
    if opp_coops <= n * 0.15:
        if n >= 15 and opp_streak_d >= 6 and rng.random() < 0.12:
            return 'C'
        return 'D'

    # Endgame exploitation: if opponent has been consistently cooperative
    if n >= 88:
        if opp_coops >= n * 0.75 and opp_streak_d == 0:
            return 'D'
        if opp_coops >= n * 0.6 and last_opp == 'C' and opp_streak_d == 0:
            return 'D'
        if opp_coops >= n * 0.5:
            return 'C'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Moderate opponent: react to streaks
    if opp_streak_d == 0:
        # opponent cooperating; cooperate but keep some pressure if we've been exploited
        if my_streak_d >= 3 and opp_coops > my_coops:
            return 'C'
        return 'C'

    if opp_streak_d == 1:
        # single defection - retaliate but forgive quickly
        if last_me == 'D':
            return 'C'
        return 'D'

    if opp_streak_d == 2:
        return 'D'

    # 3+ defections: punish, then try to reset
    if opp_streak_d >= 3:
        if my_streak_d >= 2 and rng.random() < 0.25:
            return 'C'
        return 'D'

    return 'C'
